"use client";
/* Choir, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Choir(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("choir"); }, []);
  return React.createElement("piix-pal", { "pal": "choir", ...piixAttrs(props) });
}

export default Choir;
